create or replace function public.admin_list_reports(_status text) returns table(id uuid,reporter_id uuid,reporter_name text,target_type text,target_id text,category text,details text,status text,admin_reply text,created_at timestamptz) language plpgsql stable security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'not allowed'; end if; return query select r.id,r.reporter_id,p.display_name,r.target_type,r.target_id,r.target_type,r.reason,r.status,r.resolution,r.created_at from public.admin_reports r left join public.profiles p on p.id=r.reporter_id where _status is null or _status='' or r.status=_status order by r.created_at desc limit 200; end; $$;
create or replace function public.admin_resolve_report(_report uuid,_status text,_reply text) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'not allowed'; end if; if _status not in ('open','reviewing','resolved','rejected') then raise exception 'bad status'; end if; update public.admin_reports set status=_status,resolution=nullif(_reply,''),resolved_by=(select auth.uid()),resolved_at=case when _status in ('resolved','rejected') then now() else null end where id=_report; if not found then raise exception 'report not found'; end if; end; $$;
